<script setup lang="ts">import {onMounted,ref} from 'vue';import {request} from '../api/client';import {useTask} from '../hooks/useTask';import {date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const rows=ref<{id:number;actor:string;action:string;status_code:number;created_at:string}[]>([]),{error,perform}=useTask();async function load(){rows.value=await request('/audit')}onMounted(()=>perform(load))</script><template><PageHeading no="06" title="过程留痕" sub="来源修改、任务冻结、人工决定与分发都留可追溯记录。"/><ErrorNotice :error="error"/><div class="section-line"><p class="muted">最近100次写入与导出，含权限拒绝。</p><button @click="perform(load)">刷新留痕 ↻</button></div><div class="table-scroll"><table><thead><tr><th>记录</th><th>操作者</th><th>动作</th><th>HTTP状态</th><th>时间</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>LOG {{r.id}}</td><td>{{r.actor}}</td><td>{{r.action}}</td><td><span :class="['status',r.status_code>=400?'failed':'completed']">{{r.status_code}}</span></td><td>{{date(r.created_at)}}</td></tr></tbody></table></div><p v-if="!rows.length" class="empty">首个写入或导出操作后，会出现真实留痕。</p><aside class="margin-note">逐份试样的平均秩在结果页留档；此处记录应用层操作，读取页面不会制造修改记录。</aside></template>